import json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
FILES=sorted((ROOT/'questions/science').glob('question-science-content-bb-iv-3-*.json'),key=lambda p:int(p.stem.rsplit('-',1)[1]))
ITEMS=[
('比熱比較','相同質量的甲、乙吸收相同熱量，甲升溫10℃、乙升溫20℃，哪項正確？',['甲的比熱較大','乙的比熱較大','兩者比熱相同','無法由溫升比較'],'A','Q=mcΔT；在m、Q相同時，溫升較小者比熱較大，所以甲較大。'),
('同比熱溫升','兩物質質量與比熱相同，甲吸收的熱量是乙的3倍，溫升比較為何？',['甲為乙的1/3','甲與乙相同','甲為乙的3倍','無法比較'],'C','Q=mcΔT，其他條件相同時溫升與熱量成正比，甲是乙的3倍。'),
('比熱計算','100 g物質吸收200 cal後升溫10℃，其比熱是多少？',['0.2 cal/(g·℃)','2 cal/(g·℃)','20 cal/(g·℃)','2000 cal/(g·℃)'],'A','c=Q/(mΔT)=200÷(100×10)=0.2 cal/(g·℃)。'),
('熱量計算','50 g比熱0.4 cal/(g·℃)的物質升高20℃，吸收熱量為何？',['40 cal','200 cal','400 cal','1000 cal'],'C','Q=mcΔT=50×0.4×20=400 cal。'),
('溫度變化反推','同一物質質量不變，比熱不變；若吸收熱量加倍，溫升會如何？',['加倍','減半','不變','變成零'],'A','由Q=mcΔT，在m與c固定時，Q加倍使ΔT加倍。'),
('熱平衡','等質量、不同初溫的同種水在隔熱容器混合，無熱損失時平衡溫度通常？',['介於兩初溫之間','高於兩者最高溫','低於兩者最低溫','必為0℃'],'A','熱由高溫水傳給低溫水，最後平衡溫度介於兩者初溫之間。'),
('不同質量平衡','相同初溫差下，若熱水質量遠大於冷水，混合後平衡溫度較接近？',['熱水初溫','冷水初溫','0℃','兩者平均但與質量無關'],'A','熱容量mc較大的熱水對平衡溫度影響較大，故較接近熱水初溫。'),
('海陸溫差','沿海地區日夜溫差通常較小，與水的何種性質有關？',['水的比熱較大，吸放熱時溫度變化較小','水比熱為零','水不能傳熱','水一定比陸地輕'],'A','水比熱大，吸收相同熱量時溫升較小，有助調節沿海溫度。'),
('金屬與水','同質量金屬與水吸收相同熱量，金屬溫升較大，合理推論是？',['金屬比熱小於水','金屬比熱大於水','兩者沒有比熱','金屬一定吸收較少熱量'],'A','m與Q相同時，溫升較大代表c較小。'),
('比熱與材料','比熱是物質的特性之一，正確意義是？',['單位質量升高單位溫度所需的熱量','物質總共含有的熱量','物體的質量除以溫度','溫度越高比熱必為零'],'A','比熱描述單位質量物質升高1℃所需熱量，與物質種類有關。'),
]
for p,(topic,prompt,opts,ans,ex) in zip(FILES,ITEMS):
 d=json.loads(p.read_text()); d['prompt']=prompt; d['options']=[{'id':chr(65+i),'text':t} for i,t in enumerate(opts)]; d['answer']={'value':ans,'explanation':ex}; d['solutionStrategy']=f'先整理Q、m、c與ΔT，再使用Q=mcΔT比較或反推；本題聚焦於{topic}。'; d['solutionSteps']=['先寫出已知的熱量Q、質量m、比熱c與溫度變化ΔT。','依題目要求使用Q=mcΔT，或在其他條件相同時直接比較比例。',f'代入數值或比較溫升，得到答案{ans}。',f'回看解析：{ex}','最後確認熱平衡需考慮質量與比熱，不可只取兩個初溫的簡單平均。']; d['reviewStatus']='draft'; d['updatedAt']='2026-09-08'; d['provenance']['authoringNote']='依官方課綱與公開會考、公立國中試題所呈現的比熱、熱量與溫度變化推理方向獨立改寫；未複製原題文字、選項、圖表或答案；待第二輪 AI／Terra 內容複核。'; p.write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n')
